export interface Post {
  id: string
  title: string
  content: string
  createdAt: Date
}

let posts: Post[] = []

export async function getAllPosts(): Promise<Post[]> {
  return posts
}

export async function createPost(data: { title: string; content: string }): Promise<Post> {
  const post: Post = {
    id: crypto.randomUUID(),
    title: data.title,
    content: data.content,
    createdAt: new Date(),
  }
  posts.push(post)
  return post
}

